Contract EnterValidatedCreditReferencesModule::chooseLoanRequest(requestid:Integer): LoanRequest {

            precondition:
          self.CurrentLoanRequests->exists(lr:LoanRequest | lr.RequestID = requestid)

            postcondition:
          self.CurrentLoanRequests@pre->includes(result) and result.RequestID = requestid and self.CurrentLoanRequest = result

        }
